#include <iostream>
#include <cmath>
using namespace std;

long long A1, B1, C1;

long long find_gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> A1 >> B1 >> C1;

    if (B1 <= C1) {
        long long g = find_gcd(A1, B1);
        A1 /= g;
        B1 /= g;
        cout << A1 << "/" << B1;
        return 0;
    }
    if (A1 == B1) {
        cout << "1/1";
        return 0;
    }

    double min_diff = 1e18;
    double ratio_value = double(A1) / double(B1);
    long long num_res, den_res;
    long long left_lim = 0, right_lim = B1;
    for (long long i = 1; i <= C1; ++i) {
        while (i * A1 > right_lim) {
            left_lim += B1;
            right_lim += B1;
        }
        if (i * A1 >= left_lim && i * A1 <= right_lim) {
            long long low_b = left_lim / B1;
            long long high_b = right_lim / B1;
            double low_r = double(low_b) / double(i);
            double high_r = double(high_b) / double(i);
            double diff_low = abs(ratio_value - low_r);
            double diff_high = abs(ratio_value - high_r);
            if (diff_high < diff_low) {
                if (diff_high < min_diff) {
                    min_diff = diff_high;
                    num_res = high_b;
                    den_res = i;
                }
            } else {
                if (diff_low < min_diff) {
                    min_diff = diff_low;
                    num_res = low_b;
                    den_res = i;
                }
            }
        }
    }
    long long g = find_gcd(num_res, den_res);
    num_res /= g;
    den_res /= g;
    cout << num_res << "/" << den_res;
    return 0;
}
